// Extrai e valida o JSON da resposta da IA sem o Structured Output Parser (que derruba a
// chain com "Model output doesn't fit required format" à menor sujeira) — mesma lógica do
// Doc_QA_Generation_HA, só que genérica: o formato e as chaves obrigatórias vêm do próprio
// pedido do Study Assistant (body.formato / body.chaves_obrigatorias). Se não der, o erro
// vai pra saída de erro deste nó -> próximo provedor da cascata.
const pedido = $('Webhook - Cascata IA').first().json.body || {};
const OBRIGATORIAS = Array.isArray(pedido.chaves_obrigatorias) ? pedido.chaves_obrigatorias : [];
const bruto = $input.first().json;
let texto = bruto.output ?? bruto.text ?? bruto;
if (typeof texto !== 'string') texto = JSON.stringify(texto);

if (pedido.formato !== 'json') {
  if (!String(texto).trim()) throw new Error('A IA devolveu uma resposta vazia.');
  return [{ json: { output: { text: texto } } }];
}

function tentar(s) { try { return JSON.parse(s); } catch (e) { return null; } }

let obj = tentar(texto);
if (!obj) {
  const cerca = texto.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (cerca) obj = tentar(cerca[1]);
}
if (!obj) {
  const i = texto.indexOf('{'), j = texto.lastIndexOf('}');
  if (i >= 0 && j > i) {
    const miolo = texto.slice(i, j + 1);
    obj = tentar(miolo) || tentar(miolo.replace(/,\s*([}\]])/g, '$1'));
  }
}
if (obj && obj.output && typeof obj.output === 'object' && !OBRIGATORIAS.some(k => k in obj)) obj = obj.output;
if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
  throw new Error('Resposta da IA não é um objeto JSON válido. Início: ' + String(texto).slice(0, 300));
}
const faltam = OBRIGATORIAS.filter(k => !(k in obj));
if (faltam.length) {
  throw new Error('JSON sem as chaves obrigatórias: ' + faltam.join(', ') + ' (veio: ' + Object.keys(obj).join(', ') + ')');
}
return [{ json: { output: obj } }];

